// src/rules/ai-cost/ai-key-exposed-to-client.ts
var BROWSER_ESCAPE_HATCH = /dangerouslyAllowBrowser\s*:\s*true/g;
var PUBLIC_MODEL_KEY = /(?:NEXT_PUBLIC_|VITE_|PUBLIC_|REACT_APP_|EXPO_PUBLIC_)(?:OPENAI|ANTHROPIC|CLAUDE|GEMINI|GOOGLE_AI|MISTRAL|GROQ|COHERE|REPLICATE|TOGETHER|OPENROUTER|HUGGINGFACE|DEEPSEEK)[A-Z0-9_]*(?:KEY|TOKEN|SECRET)/g;
var ai_key_exposed_to_client_default = defineRule({
  meta: {
    id: "ai-cost/ai-key-exposed-to-client",
    category: "ai-cost",
    title: "Model provider API key reachable from the browser",
    severity: "critical",
    confidence: "high",
    blocker: true,
    description: "A model provider key is exposed to client-side code, either through a public environment prefix or by constructing the SDK client with dangerouslyAllowBrowser. Provider keys are account-level credentials with no per-key spending limit by default: anyone who reads it from the bundle can spend your entire budget and access every model on the account.",
    remediation: "Keep the key on the server and call the provider from a route handler that the browser talks to instead. Remove dangerouslyAllowBrowser, drop the public prefix from the variable name, and rotate the key - assume it is compromised the moment it reaches a bundle.",
    references: [
      "https://platform.openai.com/docs/guides/production-best-practices",
      "https://help.openai.com/en/articles/5112595-best-practices-for-api-key-safety"
    ],
    tags: ["cost", "secrets", "llm"]
  },
  appliesTo: requiresModelSdk,
  checkFile(file, ctx) {
    if (isNonProductionFile(file)) return;
    let reported = 0;
    const isApplication = isDeployableApp(ctx.index);
    for (const match of file.matches(BROWSER_ESCAPE_HATCH)) {
      if (reported >= MAX_FINDINGS_PER_RULE) return;
      reported++;
      ctx.report({
        title: "SDK client constructed with dangerouslyAllowBrowser: true",
        severity: isApplication ? "critical" : "high",
        confidence: isApplication ? "high" : "low",
        blocker: isApplication,
        explanation: isApplication ? `${file.path} disables the SDK guard that prevents it from running in a browser. That guard exists because doing so puts your provider API key in code the user can read.` : `${file.path} sets dangerouslyAllowBrowser. In a library this may be a deliberate pass-through for callers who proxy the request, but any application reaching this path with a real key exposes it to the browser.`,
        evidence: [file.evidenceAt(match.index, { length: match.text.length })]
      });
    }
    for (const match of file.matches(PUBLIC_MODEL_KEY)) {
      if (reported >= MAX_FINDINGS_PER_RULE) return;
      reported++;
      ctx.report({
        title: `${match.text} is inlined into the client bundle`,
        explanation: `${file.path} reads a model provider key from ${match.text}. The public prefix means the value is compiled into the JavaScript every visitor downloads.`,
        evidence: [file.evidenceAt(match.index, { length: match.text.length })]
      });
    }
    if (!isClientReachable(file)) return;
    const provider = /process\.env\.(?:OPENAI|ANTHROPIC|GEMINI|MISTRAL|GROQ|COHERE)[A-Z0-9_]*(?:KEY|TOKEN|SECRET)/g;
    for (const match of file.matches(provider)) {
      if (reported >= MAX_FINDINGS_PER_RULE) return;
      reported++;
      ctx.report({
        title: `Model provider key referenced in client-reachable module ${file.path}`,
        confidence: "medium",
        explanation: `${file.path} is client-reachable${file.isClientComponent ? ' (it is marked "use client")' : ""} and reads ${match.text}. Server-only environment variables are undefined in the browser, so this either fails at runtime or the value is being inlined.`,
        evidence: [file.evidenceAt(match.index, { length: match.text.length })]
      });
    }
  }
});

// src/rules/ai-cost/llm-route-without-rate-limit.ts
var llm_route_without_rate_limit_default = defineRule({
  meta: {
    id: "ai-cost/llm-route-without-rate-limit",
    category: "ai-cost",
    title: "LLM endpoint with neither authentication nor rate limiting",
    severity: "critical",
    confidence: "medium",
    blocker: true,
    description: "A route that calls a language model is reachable without authentication and without any rate limit. Every request spends real money on your account. A single script pointed at this endpoint can run up a five-figure bill overnight, and the first signal is usually the invoice.",
    remediation: "Require authentication on the endpoint, then apply a per-user rate limit and a spending cap before the model call. @upstash/ratelimit works well on serverless; express-rate-limit or @fastify/rate-limit for a long-running server. Set a hard budget alert with your model provider as a backstop.",
    references: [
      "https://platform.openai.com/docs/guides/rate-limits",
      "https://owasp.org/www-project-top-10-for-large-language-model-applications/"
    ],
    tags: ["cost", "abuse", "llm"]
  },
  appliesTo(index) {
    const llmRoutes = index.routeFiles.filter((f) => hasLlmCall(f.code));
    if (llmRoutes.length === 0) {
      return {
        applicable: false,
        status: "not-applicable",
        reason: "No route handlers that call a language model were found in this project."
      };
    }
    return { applicable: true };
  },
  checkFile(file, ctx) {
    if (isNonProductionFile(file)) return;
    if (file.role !== "next-app-route" && file.role !== "next-pages-api") return;
    if (!hasLlmCall(file.code)) return;
    const authenticated = hasAuthSignal(file.text);
    const throttled = hasRateLimitSignal(file.text);
    if (authenticated && throttled) return;
    const middlewareGuards = ctx.index.withRole("next-middleware").some((m) => hasAuthSignal(m.text) || hasRateLimitSignal(m.text));
    const routePath = toRoutePath(file.path);
    const handlers = routeHandlers(file);
    const offset = handlers[0]?.offset ?? 0;
    if (!authenticated && !throttled && !middlewareGuards) {
      ctx.report({
        title: `${routePath} calls a language model with no authentication and no rate limit`,
        severity: "critical",
        blocker: true,
        explanation: `${file.path} invokes a language model from a publicly reachable endpoint. There is no session check, no API key check and no rate limiting anywhere in the module or in middleware. Anyone who finds this URL can spend your model budget in a loop.`,
        evidence: [file.evidenceAt(offset, { note: routePath })]
      });
      return;
    }
    if (!throttled && !projectHasRateLimiter(ctx.index) && !middlewareGuards) {
      ctx.report({
        title: `${routePath} calls a language model with no rate limit`,
        severity: "high",
        confidence: "medium",
        blocker: false,
        explanation: `${file.path} requires authentication but applies no rate limit before calling the model. One authenticated account - or one runaway client retry loop - can still generate unbounded spend.`,
        remediation: "Add a per-user rate limit and a usage quota before the model call, and return 429 when either is exceeded.",
        evidence: [file.evidenceAt(offset, { note: routePath })]
      });
    }
  }
});

// src/rules/ai-cost/missing-llm-timeout.ts
