    const count = category.findingCount === 0 ? c.dim("clean") : `${category.findingCount} finding${category.findingCount === 1 ? "" : "s"}`;
    lines.push(`  ${label}  ${bar}  ${colorise(String(score).padStart(3))}  ${count}`);
