  if (annotation.file !== void 0) properties.push(`file=${escapeProperty(annotation.file)}`);
  if (annotation.line !== void 0) properties.push(`line=${annotation.line}`);
  if (annotation.endLine !== void 0) properties.push(`endLine=${annotation.endLine}`);
  if (annotation.column !== void 0) properties.push(`col=${annotation.column}`);
  const suffix = properties.length > 0 ? ` ${properties.join(",")}` : "";
