      level: severityToAnnotationLevel(finding.severity),
      title: `${finding.severity.toUpperCase()}: ${finding.title}`,
      message: `${finding.explanation}

Fix: ${finding.remediation}

Rule: ${finding.ruleId} (confidence: ${finding.confidence})`,
